function net = lka_import_onnx_detector(onnxFile)
% LKA_IMPORT_ONNX_DETECTOR Imports an ONNX lane network once, optimises it for the GPU, caches it.
%
% The dlnetwork is cached next to the model as <name>_dlnetwork.mat (git-ignored),
% custom layers generated by the importer go to the namespace +lka_onnx_<name>
% in the same folder (models/perception is on the path).
%
% Graph optimisations after the import (numerically identical, checked by the parity tests):
%   - HardSwish x*clip(x+3,0,6)/6, which the importer spreads over four layers
%     (Scaling, Clip, Multiplication, Scaling; 49 times in YOLOP), becomes one
%     functionLayer: four times fewer GPU kernel launches per activation.
%   - The importer's VerifyBatchSizeLayer (the UFLDv2 export fixes batch 1) is removed so
%     several video frames can run in one batched call (the heads reshape with -1).
% The cache stores CacheVersion; a cache from an older version of this function is rebuilt.
    cacheVersion = 2;
    b = dir(onnxFile);
    if isempty(b)
        error('lka:vision:modelMissing', 'Lane model "%s" not found.', onnxFile);
    end
    d = b.folder;                             % absolute: the import runs inside d
    [~, n] = fileparts(onnxFile);
    cacheFile = fullfile(d, [n '_dlnetwork.mat']);
    if isfile(cacheFile)
        a = dir(cacheFile);
        s = load(cacheFile);
        if a.datenum >= b.datenum && isfield(s, 'CacheVersion') && s.CacheVersion == cacheVersion
            net = s.net;
            return
        end
    end
    if exist('importNetworkFromONNX', 'file') ~= 2
        error('lka:vision:onnxImporterMissing', ['Install the add-on "Deep Learning Toolbox ' ...
            'Converter for ONNX Model Format" to run ONNX lane detectors.']);
    end
    old = cd(d);
    restore = onCleanup(@() cd(old));
    net = importNetworkFromONNX(onnxFile, 'InputDataFormats', 'BCSS', ...
        'Namespace', matlab.lang.makeValidName(['lka_onnx_' n]));
    net = fuseHardSwish(net);
    net = removeBatchSizeCheck(net);
    if ~net.Initialized
        net = initialize(net);
    end
    CacheVersion = cacheVersion;
    save(cacheFile, 'net', 'CacheVersion');
end

function net = fuseHardSwish(net)
    base = @(port) extractBefore([port '/'], '/');
    hsw = @(x) x .* min(max(x + 3, 0), 6) / 6;
    L0 = net.Layers;
    clipNames = {L0(arrayfun(@(l) isa(l, 'nnet.onnx.layer.ClipLayer'), L0)).Name};
    k = 0;
    for i = 1:numel(clipNames)
        L = net.Layers;                       % graph as rewritten so far
        names = {L.Name};
        C = net.Connections;
        srcOf = @(dst) C.Source(strcmp(C.Destination, dst));
        dstOf = @(src) C.Destination(strcmp(C.Source, src));
        layer = @(name) L(strcmp(names, name));
        clip = layer(clipNames{i});
        if clip.Min ~= 0 || clip.Max ~= 6
            continue
        end
        pre = srcOf(clip.Name);
        mul = dstOf(clip.Name);
        if numel(pre) ~= 1 || numel(mul) ~= 1
            continue
        end
        preL = layer(pre{1});
        mulL = layer(base(mul{1}));
        if ~isa(preL, 'nnet.cnn.layer.ScalingLayer') || ~isequal(preL.Scale, 1) || ~isequal(preL.Offset, 3) ...
                || ~isa(mulL, 'nnet.cnn.layer.MultiplicationLayer') || mulL.NumInputs ~= 2
            continue
        end
        x = srcOf(pre{1});
        mulIn = C.Source(strcmp(cellfun(base, C.Destination, 'UniformOutput', false), mulL.Name));
        post = dstOf(mulL.Name);
        if numel(x) ~= 1 || numel(post) ~= 1 || ~all(ismember(mulIn, [x; {clip.Name}]))
            continue
        end
        postL = layer(post{1});
        if ~isa(postL, 'nnet.cnn.layer.ScalingLayer') || abs(postL.Scale - 1/6) > 1e-6 || ~isequal(postL.Offset, 0)
            continue
        end
        k = k + 1;
        newName = sprintf('hardswish_%d', k);
        consumers = dstOf(postL.Name);
        net = addLayers(net, functionLayer(hsw, 'Name', newName, 'Formattable', true, 'Acceleratable', true));
        net = connectLayers(net, x{1}, newName);
        for j = 1:numel(consumers)
            net = disconnectLayers(net, postL.Name, consumers{j});
            net = connectLayers(net, newName, consumers{j});
        end
        net = removeLayers(net, {preL.Name, clip.Name, mulL.Name, postL.Name});
    end
end

function net = removeBatchSizeCheck(net)
    L = net.Layers;
    for i = find(arrayfun(@(l) isa(l, 'nnet.onnx.layer.VerifyBatchSizeLayer'), L))'
        C = net.Connections;
        src = C.Source(strcmp(C.Destination, L(i).Name));
        dst = C.Destination(strcmp(C.Source, L(i).Name));
        net = removeLayers(net, L(i).Name);
        for j = 1:numel(dst)
            net = connectLayers(net, src{1}, dst{j});
        end
    end
end
